\textcolor{primaryblue}{\faCheckCircle\ \textbf{Summary: Infinity of Primes}}

\textbf{Euclid's Proof Strategy:}
\begin{enumerate}[leftmargin=*]
    \item Assume finitely many primes exist
    \item Construct $N = (\text{product of all primes}) + 1$
    \item Show $N$ has a prime divisor not in the list
    \item Conclude: contradiction, so infinitely many primes exist
\end{enumerate}

\textbf{Key Points:}
\begin{itemize}[leftmargin=*]
    \item The $n$th prime $p_n \leq 2^{2^{n-1}}$
    \item This bound grows extremely fast (doubly exponential)
    \item Actual primes grow much slower than this bound
    \item No largest prime exists
\end{itemize}

